export const ACADEMY_CONTENT = Object.freeze({"locale":"ko","lessons":[{"ep":1,"title":"비트코인 한 개가 그렇게 비싼데, 조금만 살 수도 있나요?","goal":"코인 수량과 결제 금액을 구분하고, 비트코인은 소수점 단위로 쪼개어 살 수 있음을 이해한다.","task":"연습 패널에서 지출 금액 100을 코인 수량으로 환산해 보세요. 실제 주문은 생성되지 않습니다.","answer":"0.002 BTC (수수료 미차감).","takeaways":["비트코인 한 개의 가격이 시작하는 데 필요한 금액은 아닙니다.","비트코인은 소수 단위로 나뉩니다. 50,000일 때 100을 쓰면 0.002 BTC를 보유하게 됩니다.","최소 주문 금액과 수수료는 플랫폼마다 다르니, 두 가지를 먼저 확인하세요."],"quiz":{"q":"비트코인 한 개가 50,000 USDT입니다. 수수료를 빼고 100 USDT를 쓰면 무엇을 얻나요?","options":["아무것도 못 산다, 한 개를 통째로 사야 한다","0.002 BTC","0.02 BTC"],"answer":1,"why":"100 ÷ 50,000 = 0.002입니다. 비트코인은 한 개의 일부만 보유할 수 있습니다."},"transcript":[{"t":0.25,"who":"sam","text":"코인 하나가 그렇게 비싸다고요? 제 돈으론 입장권도 못 사겠네요."},{"t":9.25,"who":"nexubo","text":"그건 코인 한 개 전체의 가격이지 매번 내야 하는 금액이 아니에요. 비트코인은 디지털 자산이라 소수점 단위로 가질 수 있거든요. 보통 한 개를 통째로 사진 않아요."},{"t":25.25,"who":"narrator","text":"연습 문제를 풀어볼게요. 비트코인 한 개가 50,000 USDT이고 100을 쓴다고 가정합시다. 수수료를 제외하면 0.002 비트코인입니다. 오늘의 시장 가격은 아닙니다."},{"t":45.25,"who":"sam","text":"그럼 가격이 오르내릴 땐 어떻게 되나요?"},{"t":47,"who":"nexubo","text":"보유 수량은 그대로일 수 있지만 가치는 오르내립니다. 소액으로 사면 부담은 줄지만 위험이 전혀 없는 것은 아닙니다."},{"t":62.25,"who":"nexubo","text":"쪼갤 수는 있지만 모든 플랫폼이 아주 작은 주문을 다 받아주진 않아요. 최소 주문 금액과 수수료를 확인하세요. 배울 땐 입금할 필요 없이 가상 자금을 쓰세요."},{"t":75.25,"who":"narrator","text":"비트코인을 통째로 한 개 다 사야 할까요? 아닙니다. 코인 한 개의 가격이 시작하기 위한 진입 장벽은 아닙니다."},{"t":86.25,"who":"narrator","text":"대부분의 거래는 USDT로 가격이 매겨집니다. 하지만 USDT는 정말 달러일까요? 다음 화에서 확인하세요."},{"t":92.55,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":2,"title":"USDT는 달러일까요? 코인을 살 때 왜 항상 보일까요?","goal":"스테이블코인의 용도, 페깅 목표 및 위험을 이해하고, 코인을 살 때 항상 USDT가 먼저 필요한 것은 아님을 안다.","task":"'은행 달러 예금', 'USDT', 'BTC'를 올바른 분류로 분류해 보세요.","answer":"USDT는 암호화폐 자산 중 하나인 스테이블코인입니다. 은행의 달러 예금이 아닙니다.","takeaways":["USDT는 달러와 같은 가치 근처를 유지하도록 설계된 스테이블코인이며, 은행 예금이 아닙니다.","거래소는 USDT로 가격을 매기고 자산을 교환하기 때문에, 매도하면 USDT로 받는 경우가 많습니다.","'스테이블'은 설계 목표입니다. 가격이 벗어날 수 있고, 상환에는 조건이 있습니다."],"quiz":{"q":"USDT에 대한 설명으로 맞는 것은?","options":["은행 계좌에 있는 달러 그 자체다","스테이블코인이며, 암호화폐 자산의 한 종류다","절대로 달러 가치에서 벗어나지 않는다"],"answer":1,"why":"USDT는 달러를 따라가는 것을 목표로 하지만, 발행사와 플랫폼 위험을 지닌 암호화폐 자산입니다."},"transcript":[{"t":0.25,"who":"sam","text":"테더라고 부르던데, 그럼 기본적으로 은행에 든 달러 예금인 거죠?"},{"t":9.25,"who":"nexubo","text":"아닙니다. USDT(테더)는 스테이블코인입니다. 한 달러에 가깝게 유지되도록 설계되었지만, 은행 계좌의 달러도 아니고 무위험 현금도 아닙니다."},{"t":25.25,"who":"narrator","text":"거래소에서는 자산 가격 표기와 교환에 주로 씁니다. USDT로 비트코인을 사고, 팔았을 때도 은행 계좌 입금 대신 USDT를 돌려받을 수 있습니다."},{"t":45.25,"who":"nexubo","text":"'안정'은 설계 목표이지 보증이 아닙니다. 가격이 일시적으로 흔들릴 수 있고 발행과 환매에도 조건이 붙습니다. 발행사와 플랫폼 위험도 함께 알아보세요."},{"t":62.25,"who":"sam","text":"그럼 비트코인을 사기 전에 무조건 USDT부터 사야 하나요?"},{"t":65.23,"who":"nexubo","text":"꼭 그렇진 않아요. 지원되는 법정화폐와 거래쌍은 거주 지역과 이용 플랫폼에 따라 다릅니다."},{"t":75.25,"who":"narrator","text":"이 문장은 어디가 틀렸을까요? 스테이블코인은 원금 보장 약속이 아닙니다. 용도를 정확히 알고 불안정해질 수 있음도 기억하세요."},{"t":86.25,"who":"narrator","text":"오늘 밤 휴대폰이 고장 나면 내 코인도 사라질까요? 다음 화: 내 코인은 도대체 어디에 있는가."},{"t":92.15,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":3,"title":"내 코인은 어디에 있을까: 거래소 vs 지갑","goal":"거래소 수탁 계정과 자체 보관(셀프 커스터디) 지갑을 구분하고, 접근 권한과 복구 책임을 이해한다.","task":"두 가지 시나리오를 매칭하세요: 거래소 로그인 계정과 일반 복구 구문 자체 보관 지갑.","answer":"통제권을 누가 갖는지, 복구가 어떻게 이루어지는지가 다릅니다. 자체 보관이 무조건 안전함을 뜻하진 않습니다.","takeaways":["거래소 계정에서는 주로 플랫폼이 자산과 키를 관리합니다.","셀프 커스터디 지갑에서는 내가 인증 정보를 관리하고, 복구 책임도 나에게 있습니다.","고르기 전에, 자산을 옮길 권한을 누가 가지고 있는지 물어보세요."],"quiz":{"q":"일반적인 셀프 커스터디 지갑의 복구 문구를 잃어버렸고, 다른 복구 방법도 없습니다. 어떻게 되나요?","options":["고객 지원이 초기화해 준다","접근 권한을 영영 잃을 수 있다","거래소가 자동으로 복구해 준다"],"answer":1,"why":"셀프 커스터디에서는 내가 키를 가집니다. 복구 문구나 다른 유효한 방법이 없으면 누구도 대신 복구해 줄 수 없습니다."},"transcript":[{"t":0.25,"who":"sam","text":"휴대폰이 박살 났어요. 제 코인도 같이 사라진 건가요?"},{"t":9.25,"who":"nexubo","text":"코인은 스마트폰 속에 들어있는 게 아니에요. 지갑은 블록체인 위의 자산을 조회하고 키로 승인하는 창구입니다. 복구 가능 여부는 지갑 종류와 보관한 백업 방식에 달렸습니다."},{"t":32.25,"who":"narrator","text":"거래소 수탁 계정은 플랫폼이 자산과 키를 관리하고 이용자는 계정으로 거래합니다. 자체 보관 지갑은 본인이 직접 인증 정보를 통제합니다. 편의성과 책임 분담이 다릅니다."},{"t":60.25,"who":"sam","text":"양쪽 다 비밀번호를 잊어버리면 그냥 고객센터에 문의하면 되나요?"},{"t":63.86,"who":"nexubo","text":"그렇게 생각하면 안 됩니다. 일반 복구 구문 지갑은 구문을 잃어버리고 다른 복구 수단도 없다면 고객센터에서도 찾아줄 수 없습니다."},{"t":84.25,"who":"nexubo","text":"플랫폼에 두면 플랫폼 위험이 있고, 직접 보관하면 키 유출이나 잘못된 서명 승인 위험이 있습니다. 오늘은 차이점을 이해하는 것으로 충분합니다."},{"t":103.25,"who":"narrator","text":"자산을 이동할 권한을 누가 쥐고 있는가? 먼저 이 질문에 답한 뒤, 어떤 계정이나 지갑이 필요한지 결정하세요."},{"t":116.25,"who":"narrator","text":"똑같이 생긴 두 개의 문. 하나는 가짜입니다. 다음 화: 진짜 문을 구별하는 법."},{"t":121.75,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":4,"title":"진짜 문을 찾으세요: 무작정 계정을 만들지 마세요","goal":"가입 전 공식 도메인과 거주 지역 요건을 확인하고, 기본 보안 설정을 켜는 법을 익힌다.","task":"모의 가입 페이지의 주소창에서 이상한 점을 찾아보세요.","answer":"공식 도메인 주소가 일치하지 않습니다. 의심스러운 사이트에는 정보를 입력하지 마세요.","takeaways":["무엇보다 먼저, 그 플랫폼이 내가 실제로 사는 국가에서 서비스되는지 확인하세요.","가입은 확인된 공식 경로로만, 내 이메일이나 전화번호로 하세요.","가입 직후 보안 기능을 켜고 복구 수단을 저장하세요."],"quiz":{"q":"가입하기 전에 가장 먼저 확인해야 할 것은?","options":["신규 가입 보상의 크기","플랫폼이 내 국가에서 서비스되고, 가입 경로가 공식인지","플랫폼의 팔로워 수"],"answer":1,"why":"이용 자격과 공식 경로가 먼저입니다. 보상이 계정을 열 곳을 정해서는 안 됩니다."},"transcript":[{"t":0.25,"who":"sam","text":"이곳 혜택이 엄청 큰데, 그냥 여기로 들어가면 될까요?"},{"t":9.25,"who":"nexubo","text":"보상만 보고 결정하지 마세요. 먼저 확인할 것은: 내가 사는 곳에서 허용되는지, 플랫폼이 실제 거주 국가를 지원하는지, 어떤 회사가 서비스를 제공하는지입니다. 그 다음 수수료와 입출금 규정을 살펴보세요."},{"t":32.25,"who":"narrator","text":"공식 경로를 확인한 뒤 본인의 이메일이나 휴대폰으로 가입하고, 고유 비밀번호를 설정하여 인증을 완료하세요. 타인의 계정을 사거나 신원 및 거주지를 속여선 안 됩니다."},{"t":60.25,"who":"nexubo","text":"가입이 끝이 아닙니다. 지원되는 보안 기능을 켜고, 로그인된 기기를 점검하며, 복구 수단을 보관하세요. 일회용 인증 코드를 자칭 고객센터 직원에게 절대 넘겨선 안 됩니다."},{"t":84.25,"who":"narrator","text":"저희 사이트는 정보 탐색을 돕지만, 제휴 관계가 안전을 보증하진 않습니다. 정보가 확인되지 않았다면 가입 절차를 시작하지 마세요."},{"t":103.25,"who":"sam","text":"잠깐만요. 먼저 이용 자격과 규정부터 확인하세요."},{"t":107.02,"who":"nexubo","text":"맞아요. 진짜 문을 먼저 찾고, 그다음에 계정을 만드세요."},{"t":116.25,"who":"nexubo","text":"믿을 수 있는 문을 찾으시나요? NexuAlpha는 검증된 공식 접속 경로를 제공합니다. 공식 파트너 링크를 통해 OKX에 접속하고 nexu888 코드로 수수료 환급 혜택을 받으세요."},{"t":127.35,"who":"narrator","text":"지금 바로 이중 인증을 켜세요. 다음 화: 채팅방에서 'KYC를 대신 통과해 주겠다'는 사람이 나타납니다."},{"t":134.45,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":5,"title":"KYC는 어떻게 진행되며, 신분증은 누구에게 제출해야 할까요?","goal":"신원 인증의 일반적인 목적과 절차를 이해하고, 검증된 공식 경로로만 제출해야 함을 배운다.","task":"가상의 정보를 사용하여 인증 단계를 순서대로 배열하세요. 강의에 실제 신분증을 업로드하는 것은 금지되어 있습니다.","answer":"공식 경로 확인 → 거주 지역 요건에 맞춰 본인의 실제 정보 제출 → 대기 후 결과 확인.","takeaways":["KYC는 내가 계정의 실제 주인임을 확인하고, 플랫폼이 규정을 지키도록 돕습니다.","신분증은 공식 인증 절차 안에서만 제출하고, 채팅으로는 절대 보내지 마세요.","실패하면 이유를 읽고 고친 뒤, 실제 신원으로 다시 시도하세요."],"quiz":{"q":"내 신분증은 누가 받아야 하나요?","options":["채팅방의 친절한 '상담원'","확인된 공식 인증 절차만","강의 채팅방, 다른 사람들이 봐 줄 수 있도록"],"answer":1,"why":"공식 절차만입니다. NexuAlpha는 신분증을 요구하지 않으며, 낯선 사람도 마찬가지여야 합니다."},"transcript":[{"t":0.25,"who":"sam","text":"신분증을 요구하네요. 그런데 이 사람이 자기가 대신 인증해 줄 수 있다는데요?"},{"t":9.25,"who":"nexubo","text":"신원 인증은 계정 본인 여부를 확인하고 규정을 준수하기 위한 절차입니다. 반드시 공식 페이지에서 진행하고, 채팅방 대행업자에게 신분증이나 인증 코드를 건네지 마세요."},{"t":32.25,"who":"narrator","text":"보통 실명을 입력하고 지원되는 유효 신분증을 제출한 뒤 사진이나 안면 인식 절차를 따릅니다. 주소 증명 필요 여부와 인정 신분증은 지역과 플랫폼에 따라 다릅니다."},{"t":60.25,"who":"nexubo","text":"실패했다면 원인부터 읽어보세요. 만료되었거나, 빛 반사가 있거나, 이름이 불일치하진 않나요? 안내대로 보완하되 가짜 신원으로 시도해선 안 됩니다."},{"t":84.25,"who":"sam","text":"다 하고 나면 바로 거래할 수 있나요?"},{"t":86.78,"who":"nexubo","text":"보장되지 않습니다. 심사 결과와 이용 가능 상품, 입금 가능 여부는 공식 알림을 확인해야 합니다. 본 강의에서도 실제 신분증을 일절 수집하지 않습니다."},{"t":103.25,"who":"narrator","text":"신분증은 누구에게 제출해야 할까요? 오직 검증된 공식 절차에만 제출하세요. 저희에게도, 낯선 타인에게도 절대 주지 마세요."},{"t":116.25,"who":"nexubo","text":"인증할 준비가 되셨나요? 공식 웹사이트에서만 시작하세요. OKX 파트너 링크를 통해 바로 접속하고 nexu888 코드로 수수료를 환급받으세요. 저희는 신분증을 절대 요구하지 않습니다."},{"t":127.25,"who":"narrator","text":"입금, 구매, 이체: 똑같이 생긴 세 개의 버튼. 다음 화: 어떤 버튼을 눌러야 할까요."},{"t":132.85,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":6,"title":"첫 입금: 돈은 어디서 들어오고 어디로 가는 걸까요?","goal":"법정화폐 입금, 즉시 구매, 암호화폐 입금, 내부 이체를 구분하고 경로와 수수료를 확인한다.","task":"세 가지 시나리오를 매칭하세요: 은행 법정화폐 입금, 보유 코인 입금, 계정 간 내부 이체.","answer":"경로마다 규정, 수수료, 소요 시간이 다릅니다. 내부 이체는 블록체인을 거치지 않습니다.","takeaways":["법정화폐 입금, 암호화폐 구매, 온체인 입금, 내부 이체는 서로 다른 경로입니다.","온체인 입금에는 지원되는 코인과 네트워크가 필요하고, 내부 이체는 플랫폼 안에서 이루어집니다.","플랫폼 밖에서 낯선 사람에게 절대 돈을 보내지 말고, 잔액이 어디로 들어올지 먼저 확인하세요."],"quiz":{"q":"같은 플랫폼에서 USDT를 자금 계정에서 거래 계정으로 옮깁니다. 이것은 무엇인가요?","options":["온체인 입금","내부 이체","법정화폐 입금"],"answer":1,"why":"내 계정들 사이에서 잔액만 옮기는 것입니다. 보통 온체인 전송이 아닙니다."},"transcript":[{"t":0.25,"who":"sam","text":"입금, 구매, 이체 버튼이 세 개나 있어요. 다 돈을 넣는 기능 아닌가요?"},{"t":9.25,"who":"nexubo","text":"아닙니다. 서로 다른 자산을 움직입니다. 현지 통화를 입금하나요, 기존에 가진 코인을 넣나요? 아니면 단순히 계정 간 잔고를 이동하나요?"},{"t":32.25,"who":"narrator","text":"법정화폐 입금은 계정에 현금 잔고를 채우는 것이고, 즉시 구매는 결제 후 암호화폐를 받는 것입니다. 은행이나 카드 지원, 수수료, 한도는 플랫폼마다 다릅니다."},{"t":60.25,"who":"nexubo","text":"이미 코인이 있다면 지원되는 코인과 네트워크를 선택해 입금하세요. 내부 이체는 계정 간 잔고를 재배치하는 것일 뿐 온체인 전송이 아닙니다. 잔고가 어디로 들어가는지 먼저 확인하세요."},{"t":84.25,"who":"narrator","text":"일부 플랫폼은 사용자 간 거래(P2P)도 지원하지만, 이는 일반 은행 송금과 다릅니다. 플랫폼 외부에서 개인 간 송금하지 말고, 출처 불명의 자금이나 제3자 대리 결제를 쓰지 마세요."},{"t":103.25,"who":"sam","text":"안 됩니다. 서로 다른 경로니까요."},{"t":105.59,"who":"nexubo","text":"맞아요. 먼저 자산 종류를 보고, 경로를 살핀 뒤, 실제로 입금된 내역을 확인하세요."},{"t":116.25,"who":"narrator","text":"BTC/USDT: 이 슬래시 기호는 두 코인을 동시에 산다는 뜻일까요? 다음 화: 첫 현물 거래."},{"t":122.45,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":7,"title":"첫 현물 거래: 100에서 0.002 BTC까지","goal":"정확한 금액, 수량, 수수료를 확인하며 모의 현물 매수를 완료한다.","task":"가상 잔고 1,000으로 0.002 BTC를 매수하세요. 남은 USDT 잔고 899.90과 체결 내역을 확인하세요.","answer":"체결 금액 100, 수수료 0.10, 총 지출 100.10; 잔여 899.90.","takeaways":["BTC/USDT는 USDT로 가격이 매겨진 비트코인입니다. USDT를 내고 비트코인을 받습니다.","주문 입력창의 단위가 지출 금액(USDT)인지 코인 수량(BTC)인지 먼저 확인하세요.","매수 후에는 거래 기록에서 체결 상태, 평균 가격, 수수료를 확인하세요."],"quiz":{"q":"50,000에 0.002 BTC를 사고, 0.1% 수수료가 USDT로 따로 빠집니다. 총 지출은 얼마인가요?","options":["100","100.10","110"],"answer":1,"why":"코인 값 100에 수수료 0.10을 더하면 100.10입니다."},"transcript":[{"t":0.25,"who":"sam","text":"이 슬래시 표시요. 두 코인을 다 사야 하는 건가요?"},{"t":9.25,"who":"nexubo","text":"아닙니다. 비트코인의 가격이 USDT로 매겨져 있다는 뜻이에요. 살 때는 USDT를 내고 비트코인을 받고, 팔 때는 반대로 진행됩니다."},{"t":35.25,"who":"narrator","text":"가상 계정으로 연습합니다. 선물이 아닌 현물인지 확인하세요. 거래쌍을 고르고 '매수'를 누른 뒤 금액을 입력합니다. 입력창이 지출 금액인지 코인 수량인지 확인하세요."},{"t":67.25,"who":"nexubo","text":"체결가가 50,000이고 100을 쓴다면 0.002 비트코인을 얻습니다. 수수료 0.1%가 USDT에서 별도 차감된다고 가정하면 총 100.10을 씁니다. 실제 규정은 플랫폼에 따라 다릅니다."},{"t":95.25,"who":"sam","text":"그럼 '매수'를 누르기만 하면 무조건 코인이 들어온 건가요?"},{"t":99.07,"who":"nexubo","text":"체결 내역도 확인해야 합니다. 미체결, 부분 체결, 전량 체결은 서로 다릅니다. 실제 평균 단가와 수수료도 점검하세요."},{"t":116.25,"who":"narrator","text":"첫 모의 연습은 상승과 하락을 맞히는 게 아니라 이 다섯 가지를 꼼꼼히 확인하는 것입니다. 끝나고 나서 당장 실전 거래를 하지 않아도 괜찮습니다."},{"t":131.25,"who":"nexubo","text":"실제 첫 거래를 할 준비가 되었다면, 파트너 링크를 통해 Bitget에 가입하세요. nexu888 코드로 거래 수수료 일부를 환급받을 수 있습니다. 매번 동일한 다섯 가지 점검을 잊지 마세요."},{"t":140.95,"who":"narrator","text":"가격이 올라서 팔았다고 가정해 봅시다. 그런데 왜 은행 잔고는 그대로일까요? 다음 화에서 다룹니다."},{"t":146.85,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":8,"title":"분명 팔았는데, 왜 은행 계좌에 돈이 안 들어왔을까요?","goal":"자산 매도, 스테이블코인 또는 법정화폐 잔고 수령, 실제 은행 출금을 명확히 구분한다.","task":"모의 매도를 완료한 뒤, 자금 흐름도에서 어느 단계가 실제 은행 출금인지 표시해 보세요.","answer":"USDT로 매도하는 것은 은행 출금이 아닙니다. 본 예시의 순 거래 손익: 9.79.","takeaways":["USDT로 매도하면 USDT 잔액이 생길 뿐, 은행에 돈이 들어오는 것은 아닙니다.","매도와 은행으로의 출금은 서로 다른 두 단계입니다.","가격이 올랐다고 그것이 순이익은 아닙니다. 모든 수수료를 먼저 빼세요."],"quiz":{"q":"비트코인을 팔아 USDT로 받았습니다. 지금 돈은 어디에 있나요?","options":["내 은행 계좌","플랫폼의 USDT 잔액으로","이미 우리나라 돈으로 바뀌었다"],"answer":1,"why":"받은 것은 USDT입니다. 돈을 은행으로 옮기는 것은 별도의 출금 단계입니다."},"transcript":[{"t":0.25,"who":"sam","text":"분명 팔았는데, 왜 은행 계좌에는 아직 입금이 안 된 거죠?"},{"t":9.25,"who":"nexubo","text":"어느 거래쌍으로 팔았는지 확인해 보세요. USDT로 팔았다면 USDT 잔고가 생긴 것이지 은행 입금이 된 게 아닙니다. 코인 매도와 은행 출금은 별개의 절차입니다."},{"t":35.25,"who":"narrator","text":"학습용 예시를 이어가 보죠. 0.002 비트코인을 55,000에 매도하면 110입니다. 가정된 수수료 0.11을 제하면 계정에 109.89가 들어옵니다."},{"t":67.25,"who":"sam","text":"그럼 십을 번 건가요?"},{"t":68.76,"who":"nexubo","text":"비용을 빼야죠. 환전이나 출금 수수료를 제하기 전 기준으로 여기선 9.79입니다. 시세가 올랐다고 해서 그게 전부 최종 순이익이 되는 건 아닙니다."},{"t":95.25,"who":"narrator","text":"은행으로 돈을 보내야 한다면 먼저 거주 지역 지원 여부를 확인하세요. 그런 다음 공식 경로를 통해 본인 명의 계좌로 출금하세요. 성명, 입금액, 수수료, 처리 조건을 점검하세요."},{"t":116.25,"who":"sam","text":"아닙니다."},{"t":116.98,"who":"nexubo","text":"거래와 출금 내역을 반드시 보관하세요. 자산 잔고의 성격이 불확실하다면 단순한 '성공' 메시지만 보고 판단하지 마세요."},{"t":131.25,"who":"narrator","text":"조금 더 저렴한 네트워크. 한 번의 잘못된 클릭. 코인을 영영 잃을 수도 있습니다. 다음 화: 절대 어림짐작해선 안 될 체크포인트."},{"t":137.95,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":9,"title":"코인 전송 전: 이 항목들은 절대 어림짐작하지 마세요","goal":"코인, 네트워크, 주소, 메모, 입금 반영 조건을 확인하고 반드시 소액 테스트 전송을 먼저 진행한다.","task":"의도적인 오류가 포함된 모의 출금 양식에서 네트워크 불일치와 누락된 메모를 수정한 뒤 가상 소액 테스트 전송을 진행하세요.","answer":"모든 핵심 조건이 일치할 때만 전송하세요. '올바른 네트워크로 자동 전환'되는 기본 보호 장치는 없습니다.","takeaways":["보내기 전에 받는 쪽이 지원하는 코인과 네트워크를 확인하세요.","주소는 받는 페이지에서 복사해 전체를 확인하고, 필요한 메모나 태그를 넣으세요.","먼저 소액으로 테스트하고, 입금된 것을 확인하세요."],"quiz":{"q":"받는 페이지에서 메모를 요구합니다. 어떻게 하나요?","options":["건너뛴다, 주소면 충분하다","표시된 그대로 메모를 입력한다","예전 전송의 메모를 쓴다"],"answer":1,"why":"메모나 태그가 필요한 경우, 없으면 입금이 반영되지 않을 수 있습니다."},"transcript":[{"t":0.25,"who":"sam","text":"이 네트워크가 더 저렴한데요. 그냥 이걸로 바꿔서 보내면 안 되나요?"},{"t":9.25,"who":"nexubo","text":"먼저 수신 측이 어떤 자산과 네트워크를 지원하는지 확인하세요. 수수료는 그다음입니다. 양쪽이 일치하지 않는다면 싸다고 해서 보내선 안 됩니다. 같은 USDT라도 서로 다른 네트워크에 존재할 수 있습니다."},{"t":39.25,"who":"narrator","text":"네트워크는 경로, 주소는 목적지로 생각할 수 있습니다. 하지만 두 주소가 비슷해 보여도 같은 네트워크에서 호환되지 않을 수 있습니다. 수신 플랫폼이 해당 체인과 자산을 지원하는지 반드시 확인하세요."},{"t":75.25,"who":"nexubo","text":"수신 화면에서 주소를 복사한 뒤 전체를 대조하세요. 메모나 태그가 요구되면 반드시 입력하세요. 최소 입금액, 출금 수수료, 최종 입금 수량을 확인하고 앞뒤 몇 글자만 보고 넘기지 마세요."},{"t":106.25,"who":"narrator","text":"최소 요건을 만족하는 소액 테스트 전송을 먼저 진행하고 실제 입금을 확인하세요. 이후 큰 금액을 보낼 때도 모든 항목을 다시 대조해야 하며 기존 내역을 맹신해선 안 됩니다. 자체 보관 지갑은 네트워크 수수료도 미리 준비하세요."},{"t":130.25,"who":"sam","text":"안 됩니다."},{"t":131.16,"who":"nexubo","text":"전송 전 한 번 더 대조하는 것이, 실수한 뒤 수습하러 다니는 것보다 훨씬 중요합니다."},{"t":146.25,"who":"narrator","text":"'성공'이라고 뜨는데 입금되지 않았나요? 재전송하지 마세요. 다음 화: 어디를 확인해야 할까."},{"t":151.65,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":10,"title":"전송 완료라고 뜨는데 도착하지 않았을 때, 어디를 확인해야 할까요?","goal":"발신 측 처리, 온체인 컨펌, 수신 측 입금 반영 단계를 구분하고 제한적인 구제 절차를 이해한다.","task":"세 가지 장애 시나리오를 발신 측, 온체인 상태, 수신 측과 연결하세요.","answer":"상태를 파악한 뒤 해당하는 공식 채널에 문의하세요. 원인이 불분명하다면 재전송하지 마세요.","takeaways":["제출됨, 온체인, 입금 완료는 서로 다른 세 개의 정거장입니다.","트랜잭션 해시를 해당 네트워크의 블록 탐색기에서 조회하세요.","공식 고객 지원에는 기록만 보여 주고, 복구 문구·개인 키·인증 코드는 절대 알려 주지 마세요."],"quiz":{"q":"전송이 '보냄'으로 나오는데 도착하지 않았습니다. 첫 단계는?","options":["같은 금액을 다시 보낸다","기록과 트랜잭션 해시로 어디서 멈췄는지 찾는다","되찾아 주겠다는 사람에게 돈을 낸다"],"answer":1,"why":"먼저 어느 정거장인지 찾고, 그에 맞는 공식 채널에 연락하세요. 계속 보내지 마세요."},"transcript":[{"t":0.25,"who":"sam","text":"안 들어왔네요. 시험 삼아 몇 번 더 보내볼까요?"},{"t":9.25,"who":"nexubo","text":"다시 보내지 마세요. 신청 완료, 온체인 컨펌, 계정 입금 반영은 다릅니다. 어느 단계에서 멈췄는지 먼저 파악한 뒤 문의 대상을 정하세요."},{"t":32.25,"who":"narrator","text":"전송 내역을 보관하세요. 트랜잭션 해시(TxID)가 있다면 해당 네트워크의 공식 블록 탐색기에서 상태, 도착 주소, 수량을 조회하세요. 다른 블록체인의 조회 결과와 혼동해선 안 됩니다."},{"t":60.25,"who":"nexubo","text":"수신 플랫폼에서 추가 컨펌이나 내부 검토가 진행 중일 수 있습니다. 코인, 네트워크, 주소, 메모를 잘못 입력했다면 추가 전송을 멈추고 공식 고객센터에 증빙 자료를 제출하세요."},{"t":84.25,"who":"narrator","text":"완료된 온체인 전송은 일반 작업처럼 취소할 수 없습니다. 복구 가능 여부는 기술적 환경과 플랫폼 정책에 따라 달라지며 보장되지 않습니다. 돈을 내면 무조건 되찾아준다는 말을 믿지 마세요."},{"t":103.25,"who":"sam","text":"필요한 거래 내역만 제공하고, 복구 구문이나 개인키, 인증 코드는 절대 주지 마세요."},{"t":107.92,"who":"nexubo","text":"맞아요. 먼저 어디서 멈췄는지 찾고, 무작정 다시 보내지 마세요."},{"t":116.25,"who":"narrator","text":"\"안녕하세요, 고객센터입니다. 복구 구문을 보내주세요.\" 다음 화: 사기꾼들이 진짜로 노리는 것."},{"t":122.45,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":11,"title":"수익을 내주겠다는 사람이 있다면, 먼저 무엇을 요구하는지 보세요.","goal":"비밀 인증 정보 요구, 외부 사적 입금 유도, 비정상적인 권한 승인, 원금 및 수익 보장 약속을 식별한다.","task":"네 가지 가상 대화에서 위험한 요구를 찾아내고, '중단 후 공식 채널에서 확인' 경로를 선택하세요.","answer":"누군가 개인키, 복구 구문, 인증 코드 또는 불명확한 권한 승인을 요구한다면 절대 응하지 마세요.","takeaways":["복구 문구와 개인 키는 통제권의 열쇠이지, 고객 지원용 코드가 아닙니다.","수익 보장과 돈을 내라는 압박은 위험 신호입니다.","이해하지 못한 서명이나 승인은 절대 확인하지 마세요."],"quiz":{"q":"돈을 받기 위해 안전하게 공유할 수 있는 것은?","options":["공개 주소","복구 문구","일회용 코드"],"answer":0,"why":"공개 주소는 받기 위해 만들어진 것입니다. 비밀 정보와 코드는 통제권을 넘겨줍니다."},"transcript":[{"t":0.25,"who":"sam","text":"자기가 고객센터라면서 지갑을 업그레이드해 주겠다고 하는데요."},{"t":9.25,"who":"nexubo","text":"일반 지갑에서 복구 구문은 자산의 절대적인 통제권이지 고객센터 인증 코드가 아닙니다. 개인키도 마찬가지입니다. 그 누구에게도 주지 마세요. 저희 강의 어시스턴트조차 이를 요구해선 안 됩니다."},{"t":32.25,"who":"narrator","text":"두 가지 위험 신호가 더 있습니다: 수익 보장과 결제 재촉. 거액의 수익 인증 스크린샷은 아무것도 증명하지 못합니다. 누군가 정상적인 확인 절차를 건너뛰라고 재촉한다면 즉시 멈추세요."},{"t":60.25,"who":"nexubo","text":"지갑 연결, 메시지 서명, 자산 접근 권한 승인은 완전히 다릅니다. 서명이나 승인 내용을 모른다면 확인하지 마세요. 비밀번호 입력창이 안 뜬다고 해서 위험이 없는 게 아닙니다."},{"t":84.25,"who":"narrator","text":"정보 유출이 의심된다면 즉시 작업을 멈추고 공식 보안 경로를 이용하세요. 실제 유출된 항목에 맞춰 조치하고, 상대방의 지시에 따라 원격 제어 프로그램을 설치하지 마세요."},{"t":103.25,"who":"sam","text":"입금을 위해 주소를 공유하는 것과 통제권을 넘겨주는 것은 완전히 다릅니다."},{"t":106.72,"who":"nexubo","text":"비밀을 주지 마세요. 이해하지 못한 승인은 피하세요. 결제를 재촉당하지 마세요."},{"t":116.25,"who":"narrator","text":"열한 개 강의를 마쳤습니다. 이제 진짜 돈을 입금할 때일까요? 시즌 1 피날레에 놀라운 답이 기다립니다."},{"t":123.15,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":12,"title":"시즌 1 피날레: 할 수 있는 능력을 갖추되, 하지 않을 선택권도 있습니다","goal":"종합 모의 실습을 완료하고, 거래를 하지 않는 것도 정당한 선택임을 이해하며 다음 단계를 파악한다.","task":"연습 패널에서 본 강의의 최종 점검 질문 세 가지에 답하세요.","answer":"USDT 매도는 은행 출금이 아님; 온체인 기록이 계정 입금을 뜻하진 않음; 인증 정보를 유출하지 말고 의심 시 전송 중단.","takeaways":["목표는 올바른 흐름입니다. 가입 경로와 자격, 현물, 금액과 수수료, 그리고 기록.","불분명한 전송을 멈추는 것도 정답입니다.","수료증은 학습 기록이지, 투자 자격증이 아닙니다."],"quiz":{"q":"연습 전송에서 네트워크가 잘못 표시됩니다. 올바른 행동은?","options":["그냥 보내고 운에 맡긴다","멈추고 보내지 않는다","더 큰 금액으로 바꾼다"],"answer":1,"why":"네트워크, 수수료, 신원이 불분명할 때는 과제를 끝내는 것보다 멈추는 것이 더 중요합니다."},"transcript":[{"t":0.25,"who":"sam","text":"강의를 다 마쳤어요. 그럼 이제 진짜 실전 거래를 해도 된다는 뜻인가요?"},{"t":9.25,"who":"nexubo","text":"서두르지 마세요. 오늘은 종합 모의 테스트를 합니다. 공식 접속로, 현물 여부, 금액과 수수료를 대조하고 체결 기록을 확인하세요. 의문이 남는다면 거래하지 마세요."},{"t":39.25,"who":"narrator","text":"위험을 알아차리고 차분하게 대조할 때 비로소 정답입니다. 테스트 점수가 미래의 수익을 보장하지 않습니다. 틀린 문제가 있다면 해당 강의를 복습하세요."},{"t":75.25,"who":"sam","text":"이 전송 정보는 뭔가 이상해요. 보내지 않겠습니다."},{"t":78.5,"who":"nexubo","text":"그것 역시 정답입니다. 네트워크, 수수료, 신원 정보가 불확실할 때는 억지로 거래를 끝마치는 것보다 멈추는 것이 훨씬 중요합니다."},{"t":106.25,"who":"narrator","text":"마지막으로 세 가지를 되짚어보세요: 자산은 어디로 갔는가? 실제로 얼마가 차감되었는가? 내 계정의 통제권은 누구에게 있는가? 하나라도 흐릿하다면 해당 강의로 돌아가세요."},{"t":130.25,"who":"nexubo","text":"여러분이 얻은 것은 학습 기록이지 투자를 보증하는 면허가 아닙니다. 계속 공부하거나 당분간 거래하지 않는 것 모두 훌륭한 선택입니다. 먼저 이해하고, 그다음에 행동하세요."},{"t":146.25,"who":"nexubo","text":"시작하기로 결정했다면 먼저 NexuAlpha에서 거래소를 비교하세요. 공식 파트너 링크와 코드로 가입해 수수료를 환급받고, 새로운 강의를 위해 텔레그램에 참여하세요."},{"t":157.55,"who":"narrator","text":"시즌 2: 화면에 보이는 가격이 항상 내가 내는 가격은 아닙니다. 그 이유를 밝힙니다."},{"t":163.05,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":13,"title":"화면에 보이는 가격이 왜 내 실제 체결 가격이 아닐까요?","goal":"오더북(호가창), 매수·매도 스프레드, 호가 깊이, 수수료 및 슬리피지를 이해한다.","task":"두 단계의 모의 매도 호가에서 0.002 BTC를 체결시키고 가중평균 가격을 계산하세요.","answer":"총 100.10, 교육용 수수료 차감 전 평균가 50,050. 별도로 0.1% USDT 수수료 부과 시: 수수료 0.1001, 총 지출 100.2001 (계산 전 반올림 금지).","takeaways":["최종 가격은 가장 최근의 체결이지, 어떤 수량이든 그 가격에 살 수 있다는 뜻이 아닙니다.","큰 주문은 호가창의 여러 가격대에 걸쳐 체결될 수 있습니다.","슬리피지와 거래 수수료는 별개의 비용입니다. 명세를 확인하세요."],"quiz":{"q":"0.002 BTC 중 절반은 50,000에, 나머지 절반은 50,100에 체결됐습니다. 평균 가격은?","options":["50,000","50,050","50,100"],"answer":1,"why":"같은 양의 두 절반을 평균하면 50,050입니다. 수수료는 그 위에 붙는 별도 비용입니다."},"transcript":[{"t":0.25,"who":"sam","text":"방금 전까진 이 가격이었는데, 왜 제 결제 금액은 다른 거죠?"},{"t":9.25,"who":"nexubo","text":"화면의 현재가는 직전에 체결된 거래의 기록일 뿐 무제한 물량의 제시가가 아닙니다. 지금 사람들이 얼마에 얼마나 사고팔길 원하는지는 호가창(오더북)에 있습니다."},{"t":32.25,"who":"narrator","text":"0.002 비트코인을 산다고 가정해 보죠. 첫 번째 호가에는 절반 물량만 있습니다. 나머지 절반은 더 높은 호가에서 체결됩니다. 합치면 평균 단가는 50,000이 아니라 50,050이 됩니다."},{"t":60.25,"who":"nexubo","text":"슬리피지는 기대했던 가격과 실제 체결된 가격의 차이입니다. 항상 불리하게만 작용하진 않습니다. 거래 수수료는 별개의 비용입니다. '무료'라는 슬로건 속에 둘을 뭉뚱그리지 마세요."},{"t":84.25,"who":"narrator","text":"주문 규모가 크거나, 호가 잔량이 얇거나, 시장이 급변할수록 기대 가격에서 벗어날 가능성이 커집니다. 주문 전에는 금액과 호가 깊이를, 체결 후에는 실제 평균 단가를 확인하세요."},{"t":103.25,"who":"sam","text":"아닙니다."},{"t":104.04,"who":"nexubo","text":"최종 결제 내역을 확인해야 비로소 체결을 알 수 있습니다. 화면에서 가장 크게 보이는 숫자만 바라보지 마세요."},{"t":116.25,"who":"nexubo","text":"수수료는 실제로 낮출 수 있는 비용 중 하나입니다. NexuAlpha에서 수수료를 비교하고 파트너 링크와 추천 코드로 가입해 수수료를 환급받으세요. 비용은 줄지만 위험은 그대로입니다."},{"t":126.75,"who":"narrator","text":"매수 주문을 넣었는데 체결되지 않네요. 고장 난 걸까요? 다음 화: 시장가, 지정가, 그리고 주문 취소."},{"t":132.45,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":14,"title":"시장가, 지정가, 주문 취소: 각각 언제 써야 할까요?","goal":"'체결 우선' 또는 '가격 경계 우선'에 따라 주문을 선택하고, 미체결 및 부분 체결을 이해하기.","task":"가상 지정가 주문을 넣고 부분 체결을 관찰한 뒤, 남은 수량을 취소하세요.","answer":"가격 조건이 맞아도 체결 가능 수량의 영향을 받으며, 이미 체결된 부분은 주문 취소로 되돌릴 수 없습니다.","takeaways":["시장가 주문은 지금 가능한 가격으로 빠르게 체결되며, 최종 가격은 움직일 수 있습니다.","지정가 주문은 가격의 한도를 정해 주지만, 체결되지 않을 수도 있습니다.","취소는 미체결 부분에만 적용되고, 이미 체결된 부분은 그대로 남습니다."],"quiz":{"q":"지정가 주문이 절반 체결된 상태에서 취소했습니다. 어떻게 되나요?","options":["모든 것이 되돌려진다","미체결된 절반만 취소된다","체결된 절반이 시장가 주문으로 바뀐다"],"answer":1,"why":"취소로 체결을 되돌릴 수는 없습니다. 남은 수량만 멈춥니다."},"transcript":[{"t":0.25,"who":"sam","text":"매수를 눌렀는데 왜 계속 체결이 안 되죠?"},{"t":9.25,"who":"nexubo","text":"시장가 주문은 현재 체결 가능한 호가로 빠르게 체결되는 것을 우선시하지만 최종 가격이 변할 수 있습니다. 지정가 주문은 매수 상한가나 매도 하한가를 정하지만 체결을 보장하지는 않습니다."},{"t":32.25,"who":"narrator","text":"현재가보다 낮게 사고 싶다면 대기해야 할 수 있습니다. 반대로 지정가 주문이 이미 상대 호가 조건을 만족한다면 즉시 체결될 수도 있어, 모든 지정가 주문이 줄을 서는 것은 아닙니다."},{"t":60.25,"who":"sam","text":"그럼 주문을 취소하면 방금 매수한 것도 되돌려지나요?"},{"t":62.82,"who":"nexubo","text":"아닙니다. 취소는 아직 체결되지 않은 부분만 처리하며, 이미 체결된 거래는 되돌릴 수 없습니다."},{"t":84.25,"who":"narrator","text":"상태를 명확히 확인한 후 조작하세요. 메이커인지 테이커인지는 실제 체결 방식에 따라 결정되며, 지정가를 선택했다고 해서 특정 수수료율이 보장되는 것은 아닙니다."},{"t":103.25,"who":"sam","text":"체결되지 않습니다."},{"t":104.12,"who":"nexubo","text":"주문 유형을 고르는 것은 실행 방식을 선택하는 것이지 소원을 비는 것이 아닙니다."},{"t":116.25,"who":"narrator","text":"양봉 캔들은 다음 캔들도 오른다는 뜻일까요? 다음 화에서 이어집니다."},{"t":121.05,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":15,"title":"캔들 하나가 알려주는 네 가지 핵심 정보는?","goal":"시가, 고가, 저가, 종가와 시간 단위를 읽고, 색상이나 캔들 하나를 미래 예측으로 여기지 않기.","task":"가상 캔들에서 시가, 고가, 저가, 종가를 클릭하고 차트 주기를 확인하세요.","answer":"50,000 / 51,000 / 49,000 / 50,500; 오 분 주기.","takeaways":["캔들 하나는 한 기간의 네 가지 가격을 보여 줍니다. 시가, 고가, 저가, 종가입니다.","모양보다 시간 단위를 먼저 읽으세요. 분봉과 일봉은 다릅니다.","앱마다 색이 다르고, 캔들 하나는 기록일 뿐 예측이 아닙니다."],"quiz":{"q":"오 분봉 캔들이 50,000에 시작해 51,000까지 오르고, 49,000까지 내려갔다가 50,500에 끝났습니다. 고가는?","options":["50,500","51,000","49,000"],"answer":1,"why":"윗꼬리의 끝이 그 기간의 가장 높은 가격입니다. 51,000."},"transcript":[{"t":0.25,"who":"sam","text":"초록색이면 다음 순간에도 오른다는 뜻인가요?"},{"t":9.25,"who":"nexubo","text":"캔들 하나는 특정 기간의 네 가지 가격(시가, 고가, 저가, 종가)을 기록합니다. 이는 가상의 오 분 봉 데이터이며 향후 오 분을 보장하지 않습니다."},{"t":32.25,"who":"narrator","text":"몸통은 시가와 종가의 차이를 보여주고, 꼬리는 해당 기간의 고점과 저점을 표시합니다. 아직 마감되지 않은 캔들은 새로운 체결에 따라 계속 변합니다."},{"t":60.25,"who":"sam","text":"주기를 바꾸면 왜 차트 모양이 달라 보이나요?"},{"t":63.75,"who":"nexubo","text":"각 캔들이 나타내는 시간의 길이가 달라졌기 때문입니다. 형태를 논하기 전에 주기부터 확인해야 하며, 오 분을 하루처럼 다뤄선 안 됩니다."},{"t":84.25,"who":"narrator","text":"앱마다 상승과 하락을 나타내는 색상이 다를 수 있으므로 범례와 숫자를 확인해야 합니다. 과거 추세는 참고 정보일 뿐, 단일 캔들이 다음 등락을 보장하지 않습니다."},{"t":103.25,"who":"sam","text":"고가 51,000, 종가 50,500."},{"t":108.91,"who":"nexubo","text":"먼저 기록을 읽고, 기록을 예언으로 착각하지 마세요."},{"t":116.25,"who":"narrator","text":"\"1,000이 있고 20만 잃고 싶다면 전액 매수할까?\" 다음 화: 얼마를 잃을 수 있는지 먼저 정하라."},{"t":122.35,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":16,"title":"얼마어치 살지보다 얼마까지 잃어도 되는지 먼저 정하세요","goal":"계정 잔고, 포지션 규모, 계획된 리스크는 서로 다른 세 개의 숫자임을 이해하기.","task":"주어진 진입가, 스탑로스 폭, 교육용 리스크 예산에 따라 가상 포지션을 계산하세요.","answer":"400 USDT 명목 현물 금액; 0.008 BTC; 수수료 및 체결 오차는 별도 계산 필요.","takeaways":["계좌 잔액, 포지션 크기, 계획한 위험은 서로 다른 세 숫자입니다.","먼저 청산 지점을 정하고, 그다음 포지션 크기를 정하세요.","손절 폭 5%, 위험 예산 20이라면 포지션은 약 400입니다."],"quiz":{"q":"진입 50,000, 계획한 청산 47,500, 감수할 손실은 20입니다. 포지션은 대략 얼마인가요?","options":["20","400","4,000"],"answer":1,"why":"청산 지점까지 5%이고, 400의 5%는 20입니다. 비용은 그 위에 더해집니다."},"transcript":[{"t":0.25,"who":"sam","text":"1,000이 있고 20만 잃고 싶다면 일단 전액 매수하면 되나요?"},{"t":9.25,"who":"nexubo","text":"계정에 얼마가 있는지, 이번에 얼마를 사는지, 최대 얼마의 손실을 감수할 계획인지는 서로 다른 세 가지 문제입니다. 청산 조건이 먼저 정해져야 포지션을 산출할 수 있습니다."},{"t":35.25,"who":"narrator","text":"연습 문제를 하나 보죠. 50,000에 진입해 47,500에 퇴출할 계획이라면 5% 차이입니다. 비용을 제외하고 가격 손실 20을 감수한다면 포지션 규모는 약 400이 됩니다."},{"t":67.25,"who":"sam","text":"'최대 20만 손실'이 '20어치만 매수'한다는 뜻은 아니었군요?"},{"t":70.55,"who":"nexubo","text":"맞습니다. 400짜리 포지션이 5% 하락해야 20에 해당합니다. 이는 교육용 예시일 뿐입니다."},{"t":95.25,"who":"narrator","text":"실제 시장에는 슬리피지, 갭, 수수료, 체결 실패가 발생하므로 계획된 리스크가 손실 상한을 보장하지는 않습니다. 대출을 받거나 생계 필수 자금으로 연습하지 마세요."},{"t":116.25,"who":"sam","text":"이십입니다."},{"t":116.98,"who":"nexubo","text":"받아들일 수 있는 최악의 상황을 먼저 계산한 뒤, 이 거래가 정말 필요한지 판단하세요."},{"t":131.25,"who":"narrator","text":"스탑로스를 설정하면 딱 그 금액만큼만 잃게 될까요? 다음 화: 스탑로스의 진실."},{"t":137.75,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":17,"title":"익절과 손절은 계획일 뿐, 보험이 아닙니다","goal":"트리거(발동)와 체결의 차이를 이해하고, 스탑 시장가와 스탑 지정가의 서로 다른 리스크를 구분하기.","task":"동일한 급락 상황에서 스탑 시장가와 스탑 지정가 주문의 시뮬레이션 결과를 비교해 보세요.","answer":"전자는 슬리피지가 발생할 수 있고, 후자는 체결되지 않을 수 있습니다. 둘 다 원금 보장 보험이 아닙니다.","takeaways":["손절 주문은 청산 계획을 실행하는 것이지, 보험이 아닙니다.","스톱 마켓 주문은 빠르게 빠져나오지만, 빠른 장에서는 슬리피지가 생길 수 있습니다.","스톱 리밋 주문은 가격에 한도를 두지만, 아예 체결되지 않을 수도 있습니다."],"quiz":{"q":"급락 상황에서 스톱 리밋 주문에 무슨 일이 생길 수 있나요?","options":["항상 트리거 가격에 체결된다","가격이 빠르게 지나가 버리면 체결되지 않을 수 있다","보험으로 바뀐다"],"answer":1,"why":"지정가가 가격을 지켜 주기 때문에, 시장이 빠르게 움직이면 주문이 미체결로 남을 수 있습니다."},"transcript":[{"t":0.25,"who":"sam","text":"스탑로스를 설정했으니 제가 입력한 금액만큼만 손실을 보겠죠?"},{"t":9.25,"who":"nexubo","text":"스탑로스는 조건 도달 시 퇴출 계획을 실행하는 도구일 뿐 보험이 아닙니다. 조건이 발동되었다고 해서 반드시 그 가격에 체결되거나 손실이 정확히 거기서 멈추지는 않습니다."},{"t":32.25,"who":"narrator","text":"발동 후 시장가로 실행되어 빠른 탈출을 우선하지만 실제 체결가에 슬리피지가 발생할 수 있습니다. 급변장이나 호가창이 얇을 때는 차이가 더 커질 수 있습니다."},{"t":60.25,"who":"nexubo","text":"발동 후 지정가로 걸어 수용 가능한 가격을 제한하지만, 가격이 급락해 통과해 버리면 체결되지 않을 수 있습니다. 어느 한쪽이 무조건 우월한 것이 아니라 트레이드오프입니다."},{"t":84.25,"who":"narrator","text":"설정 후 방향, 수량, 주문 상태를 점검하세요. 선물 거래에서는 어떤 가격으로 트리거되는지 확인하여 강제 청산이 먼저 일어나는 위치에 스탑을 두지 않도록 해야 합니다."},{"t":103.25,"who":"sam","text":"보장되지 않습니다."},{"t":104.72,"who":"nexubo","text":"한계를 이해해야 스탑로스를 부적이 아닌 실질적인 계획으로 활용할 수 있습니다."},{"t":116.25,"who":"narrator","text":"둘 다 BTC라고 적혀 있지만, 하나는 비트코인을 전혀 주지 않을 수도 있습니다. 다음 화: 현물과 선물."},{"t":123.15,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":18,"title":"현물과 선물: 같은 코인이라도 전혀 다른 상품입니다","goal":"자산 보유와 가격 계약 보유를 구분하고, 롱(매수)과 숏(매도) 포지션의 방향을 이해하기.","task":"현물 자산 잔고와 선물 포지션 항목을 각각 올바른 화면에 연결하세요.","answer":"선물 포지션은 출금 가능한 기초 암호화폐 자산과 동일하지 않습니다. 본 강의는 실제 계좌 개설을 요구하지 않습니다.","takeaways":["현물은 한 자산을 다른 자산으로 바꾸는 것이고, 무기한 선물은 계약 포지션입니다.","롱은 가격이 오르면, 숏은 가격이 내리면 이익입니다. 반대편에 서면 손실입니다.","선물은 다른 위험 구조이지, 반드시 도달해야 하는 단계가 아닙니다."],"quiz":{"q":"선물 포지션으로 출금할 수 있는 비트코인이 생기나요?","options":["네, 현물과 같다","아니요, 손익을 정산하는 계약이다","10x 레버리지일 때만"],"answer":1,"why":"선형 무기한 선물은 계약 안에서 손익을 정산합니다. 출금 가능한 코인 잔액이 아닙니다."},"transcript":[{"t":0.25,"who":"sam","text":"둘 다 비트코인이라고 적혀 있는데, 같은 매매 아닌가요?"},{"t":9.25,"who":"nexubo","text":"대출이 없는 일반 현물은 한 자산을 다른 자산으로 직접 교환합니다. 여기서 다루는 선형 무기한 계약은 가격 변동에 따라 손익을 정산하는 계약 포지션을 보유하는 것일 뿐, 출금 가능한 비트코인을 사는 것이 아닙니다."},{"t":32.25,"who":"narrator","text":"롱은 보통 가격 상승을 기대하고, 숏은 하락을 기대합니다. 방향을 잘못 판단하면 양쪽 모두 손실을 봅니다. 숏 포지션이 가능하다고 해서 돈을 더 쉽게 벌 수 있는 것은 아닙니다."},{"t":60.25,"who":"sam","text":"현물에서 선물로 업그레이드해야 할까요?"},{"t":62.38,"who":"nexubo","text":"그럴 필요 없습니다. 선물은 또 다른 리스크 구조일 뿐 필수로 거쳐야 할 상위 단계가 아닙니다. 구조를 이해하고 이용하지 않기를 선택할 수도 있습니다."},{"t":84.25,"who":"narrator","text":"대출 없는 일반 현물은 선물처럼 마진 부족으로 인한 강제 청산은 없지만, 자산 가치가 크게 폭락할 위험은 여전히 있습니다. 강제 청산이 없다고 해서 원금이 보장되는 것은 아닙니다."},{"t":103.25,"who":"sam","text":"아닙니다."},{"t":103.9,"who":"nexubo","text":"레버리지를 연구하기 전에 거래 대상이 무엇인지부터 분명히 구분하세요."},{"t":116.25,"who":"narrator","text":"10배 레버리지를 쓰면 거래소가 900을 공짜로 줄까요? 다음 화에서 이어집니다."},{"t":121.25,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":19,"title":"10배 레버리지: 수익이 커질까요, 위험이 커질까요?","goal":"증거금, 명목 포지션, 수익률을 구분하고, 고정 포지션 규모에서 레버리지 설정 효과를 이해하기.","task":"고정 증거금과 고정 포지션 모드를 각각 선택하고, 가격 변동에 따른 금액 손익을 관찰하세요.","answer":"고정 증거금에서 레버리지를 높이면 명목 포지션이 커지지만, 고정 포지션에서는 금액 손익이 저절로 커지지 않습니다.","takeaways":["증거금 100으로 1,000 포지션을 운용하면 10x 레버리지입니다.","가격 변동은 포지션 전체에 작용하고, 그 결과는 증거금이 떠안습니다.","포지션 크기가 같다면, 레버리지를 바꿔도 달라지는 것은 증거금이지 손익이 아닙니다."],"quiz":{"q":"1,000 포지션이 불리한 방향으로 1% 움직였습니다(수수료 제외). 대략 얼마를 잃나요?","options":["1","10","100"],"answer":1,"why":"1,000 포지션의 1%는 약 10이며, 증거금에서 빠집니다."},"transcript":[{"t":0.25,"who":"sam","text":"열 배로 설정하면 거래소가 900을 그냥 주는 건가요?"},{"t":9.25,"who":"nexubo","text":"현금을 공짜로 주는 것이 아닙니다. 단순화해 말하면, 100의 증거금으로 1,000의 명목 포지션을 굴리는 것이 10배 레버리지입니다. 가격 변동은 전체 포지션에 적용되고, 내 증거금이 그 손익을 감당합니다."},{"t":35.25,"who":"narrator","text":"수수료를 제외하면, 가격이 반대로 1% 움직일 때 1,000 포지션은 약 10을 잃고, 2,000 포지션은 약 20을 잃습니다. 퍼센트는 작아 보여도 소액 증거금에는 매우 치명적일 수 있습니다."},{"t":67.25,"who":"nexubo","text":"흔히 하는 또 다른 착각: 포지션 규모가 그대로이고 레버리지 설정만 바꾼다면, 동일한 가격 변동에 따른 금액 손익이 갑자기 두 배로 뛰지 않습니다. 주로 변하는 것은 요구 증거금과 위험 완충력입니다."},{"t":95.25,"who":"narrator","text":"실제 강제 청산은 유지 증거금, 시장 평균가(Mark Price), 수수료 등이 복합적으로 작용하므로 10배라고 해서 정확히 10% 떨어져야 청산되는 것은 아닙니다. 이 어림값으로 실전 거래를 설정하지 마세요."},{"t":116.25,"who":"sam","text":"그렇지 않습니다."},{"t":117.06,"who":"nexubo","text":"확대되는 것은 원금에 미치는 포지션의 영향력이지, 시장 판단력이 아닙니다."},{"t":131.25,"who":"narrator","text":"증거금이 바닥나기 전에 강제 종료될 수 있는 이유는? 다음 화: 보이지 않는 경계선."},{"t":137.05,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":20,"title":"증거금이 0이 되기 전에 강제 청산될 수 있는 이유는?","goal":"개시 증거금, 유지 증거금, 순자산(Equity), 사용 가능 잔고를 명확히 구분하기.","task":"초기 100, 평가손실 20(수수료 미포함)일 때 단순화된 순자산 80을 기입하고 변동 필드를 확인하세요.","answer":"순자산 80; 유지 요건은 상품 규칙에 따라 별도 계산해야 하며 개시 증거금과 동일하다고 간주해서는 안 됩니다.","takeaways":["개시 증거금은 포지션을 열 때, 유지 증거금은 포지션을 유지할 때 필요합니다.","자산 가치는 증거금에 미실현 손익을 더하거나 뺀 것입니다. 100에서 20 손실이면 80이 남습니다.","증거금이 바닥나기 전에 위험 관리 시스템이 개입할 수 있습니다."],"quiz":{"q":"개시 증거금이 100이고 포지션이 20 손실입니다(수수료 제외). 단순화한 자산 가치는?","options":["100","80","120"],"answer":1,"why":"100에서 손실 20을 빼면 80이 남고, 가격이 더 불리하게 움직이면 여유분은 계속 줄어듭니다."},"transcript":[{"t":0.25,"who":"sam","text":"아직 잔고가 남아 있는데 왜 계속 기다리게 놔두지 않나요?"},{"t":9.25,"who":"nexubo","text":"포지션을 열 때는 개시 증거금이 필요합니다. 포지션이 열려 있는 동안에는 유지 증거금 요건도 충족해야 하죠. 처음에 넣은 금액이 앞으로도 계속 똑같은 버퍼가 되어주진 않습니다."},{"t":35.25,"who":"narrator","text":"개시 증거금이 100이고 포지션 손실이 20이라고 해보죠. 다른 조건을 제외하면 순자산은 이제 80입니다. 가격이 계속 불리하게 움직이면 버퍼는 계속 줄어듭니다."},{"t":67.25,"who":"nexubo","text":"순자산이 플랫폼의 유지 수준에 가까워지면 리스크 시스템이 개입할 수 있습니다. 0이 될 때까지 기다릴 필요가 없죠. 계정 유형, 마진 모드, 상품 규칙에 따라 다릅니다."},{"t":95.25,"who":"sam","text":"그럼 돈을 계속 추가하면 안전한가요?"},{"t":99.06,"who":"nexubo","text":"돈을 추가한다고 해서 가격 방향이 바뀌진 않으며, 청산당하지 않는다고 보장하지도 않습니다. 오히려 더 많은 자금을 동일한 위험으로 끌어들일 수 있죠."},{"t":116.25,"who":"sam","text":"아닙니다. 하나는 진입 조건이고, 다른 하나는 포지션 유지 조건입니다."},{"t":121.2,"who":"nexubo","text":"먼저 순자산을 확인한 다음, 경고선에서 얼마나 떨어져 있는지 확인하세요."},{"t":131.25,"who":"narrator","text":"100을 작은 상자에 넣으면 나머지 900은 영원히 안전할까요? 다음 화: 격리 마진."},{"t":137.95,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":21,"title":"격리 마진: 이 거래를 독립된 작은 상자에 담기","goal":"단일 포지션 증거금 격리와 증거금 추가가 위험 노출 자금을 확대할 수 있음을 이해하기.","task":"시뮬레이션 설정에서 자동 추가 스위치를 찾고, 이것이 리스크를 감당하는 자금을 어떻게 바꾸는지 설명하세요.","answer":"자동 또는 수동 증거금 추가는 투입 증거금을 늘립니다. 무조건 초기 투입 금액만 잃는다고 단정할 수 없습니다.","takeaways":["격리 마진은 한 포지션에 전용 증거금을 줍니다.","배정한 증거금은 여전히 잃을 수 있습니다. 격리 마진은 손절이 아닙니다.","자동 추가든 수동 추가든, 같은 위험에 더 많은 돈을 거는 것입니다."],"quiz":{"q":"격리 포지션에 증거금 자동 추가를 켰습니다. 무엇이 달라지나요?","options":["달라지는 것 없음, 손실은 처음 100으로 제한된다","잔액이 더 많이 포지션으로 흘러들 수 있다","포지션이 무위험이 된다"],"answer":1,"why":"자동 추가는 사용 가능한 잔액을 포지션으로 옮기므로, 더 많은 돈이 위험을 떠안게 됩니다."},"transcript":[{"t":0.25,"who":"sam","text":"격리 마진에 100을 넣으면 나머지 900은 영원히 안전한가요?"},{"t":9.25,"who":"nexubo","text":"격리 마진의 핵심은 포지션마다 독립된 증거금을 배정하는 것입니다. 추가 증거금을 넣지 않고 자동 추가도 켜지 않은 단순 조건에서는, 할당된 증거금만이 청산 위험을 부담합니다."},{"t":32.25,"who":"narrator","text":"포지션별 증거금 범위를 구분하기에는 유용합니다. 하지만 이 100 자체가 손실될 수 있으며, 격리 마진이 손실을 없애주거나 스탑로스를 대신하지는 않습니다."},{"t":60.25,"who":"nexubo","text":"이 스위치를 주의하세요: 일부 플랫폼은 자동 증거금 추가 기능을 제공합니다. 이를 켜면 사용 가능 잔고가 포지션으로 계속 유입될 수 있습니다. 수동 추가도 마찬가지로 더 많은 자금을 위험에 빠뜨립니다."},{"t":84.25,"who":"narrator","text":"'격리'라는 글자만 보고 최대 손실이 무조건 처음의 100에 머문다고 단정하지 마세요. 증거금 추가 설정, 수수료, 상품 규칙을 꼼꼼히 확인해야 합니다."},{"t":103.25,"who":"sam","text":"불가능합니다."},{"t":103.99,"who":"nexubo","text":"격리 마진은 격리 범위뿐만 아니라 외부에서 추가로 연결된 파이프라인이 있는지도 봐야 합니다."},{"t":116.25,"who":"narrator","text":"한 포지션에서 물이 새자 다른 포지션까지 가라앉기 시작합니다. 다음 화: 교차 마진."},{"t":121.15,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":22,"title":"교차 마진: 한 포지션의 손실이 다른 포지션까지 위협하는 이유","goal":"단일 마진 풀의 공유 리스크를 이해하고, 교차 마진이 개인의 모든 자산에 적용된다고 착각하지 않기.","task":"가상 포지션 하나를 손실 상태로 만들고 동일한 풀의 리스크 변화를 관찰한 뒤, 이 마진 풀에 속하지 않는 자산에 동그라미를 치세요.","answer":"리스크는 동일한 마진 풀 전체로 번질 수 있습니다. 개인의 모든 자산으로 자동 확장되는 것은 아닙니다.","takeaways":["교차 마진은 여러 포지션이 하나의 증거금 풀을 함께 씁니다.","손실 중인 포지션 하나가 다른 포지션들이 의지하는 여유분을 먹어 버릴 수 있습니다.","은행 카드나 개인 지갑까지 건드리지는 않습니다."],"quiz":{"q":"교차 마진은 자동으로 더 안전한가요?","options":["네, 절대 청산되지 않는다","꼭 그렇지는 않다, 공유 풀과 규칙에 달려 있다","네, 모든 은행 카드를 사용한다"],"answer":1,"why":"추가 증거금은 위험 처리를 늦출 수 있지만, 그만큼 더 많은 돈을 위험에 노출시킵니다."},"transcript":[{"t":0.25,"who":"sam","text":"손실은 왼쪽에서 났는데, 왜 오른쪽 포지션까지 위험해지는 거죠?"},{"t":9.25,"who":"nexubo","text":"교차 마진은 규칙이 허용하는 범위 내에서 여러 포지션 간에 증거금을 공유합니다. 한 마진 풀에 1,000이 있다고 가정하면, 여러 포지션이 처음에 각자 할당받은 금액뿐만 아니라 이 풀 전체에 의존할 수 있습니다."},{"t":39.25,"who":"narrator","text":"손실 중인 포지션 하나가 다른 포지션들이 의존하는 버퍼를 갉아먹을 수 있습니다. 손익, 미체결 주문에 묶인 증거금, 담보 가치 변동 모두가 동일한 계정의 리스크에 영향을 줍니다."},{"t":75.25,"who":"sam","text":"그럼 교차 마진은 청산당하기 더 어려우니까 더 안전한 건가요?"},{"t":79.67,"who":"nexubo","text":"추가 자금이 있으면 포지션이 위험 관리에 들어가는 시점을 늦출 수는 있습니다. 하지만 손실을 감당하기 위해 더 많은 자금을 위험에 노출시키는 것이기도 합니다."},{"t":106.25,"who":"narrator","text":"교차 마진이라고 해서 플랫폼이 개인의 은행 카드나 개인 지갑을 마음대로 사용할 수 있는 것은 아닙니다. 어떤 계정과 담보가 인정되는지는 상품 규칙에 따릅니다. 복잡한 담보는 할인율(haircut)과 고유한 가격 리스크가 따를 수도 있습니다."},{"t":130.25,"who":"sam","text":"꼭 그렇지는 않습니다. 공유 풀과 계정 규칙에 따라 다릅니다."},{"t":135.19,"who":"nexubo","text":"단일 포지션의 상자만 보지 말고, 풀 전체를 살펴보아야 합니다."},{"t":146.25,"who":"narrator","text":"지켜보던 가격은 아직 도달하지 않았는데 경보가 울립니다. 다음 화: 강제 청산 버튼은 누가 누르는가."},{"t":152.55,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":23,"title":"강제 청산: 내 포지션은 왜 자동으로 정리될까요?","goal":"강제 청산 트리거, 시장 평균가(Mark Price), 유지 증거금 요건을 이해하고, 레버리지의 역수를 절대적인 공식으로 여기지 않기.","task":"하락 후 반등하는 동일한 가상 시장을 재생하고, 일반 현물과 단순화된 격리 계약을 각각 관찰해 보세요.","answer":"경로 리스크가 중요합니다. 중간에 강제 청산된 계약은 나중에 가격이 반등해도 복구되지 않습니다.","takeaways":["많은 무기한 선물은 최종 체결가가 아니라 마크 가격과 증거금 규칙으로 청산을 판단합니다.","유지 증거금 요건에 가까워지면 시스템이 포지션을 줄이거나 종료할 수 있습니다.","종료된 포지션은 가격이 반등해도 돌아오지 않습니다."],"quiz":{"q":"레버리지 포지션이 청산됐고, 나중에 가격이 다시 올랐습니다. 어떻게 되나요?","options":["포지션이 저절로 돌아온다","종료된 상태 그대로다, 그 과정이 중요했다","거래소가 손실을 환불해 준다"],"answer":1,"why":"강제 청산되면 포지션은 사라집니다. 이후의 반등은 아직 보유 중인 사람에게만 도움이 됩니다."},"transcript":[{"t":0.25,"who":"sam","text":"내가 보고 있는 가격은 아직 거기에 안 갔는데, 왜 경보가 울리는 거죠?"},{"t":9.25,"who":"nexubo","text":"마지막 체결가가 항상 강제 청산을 판단하는 기준 가격은 아닙니다. 많은 무기한 계약이 시장 평균가(Mark Price)와 마진 규칙으로 리스크를 평가합니다. 이용하는 플랫폼이 어떤 규칙을 쓰는지 확인하세요."},{"t":35.25,"who":"narrator","text":"가격이 포지션과 반대로 움직이면 손실이 순자산을 잠식합니다. 유지 증거금 수준에 가까워지면 시스템이 주문을 취소하거나 포지션을 줄이거나 강제로 종료할 수 있습니다. 사용자의 동의를 기다려주지 않습니다."},{"t":67.25,"who":"nexubo","text":"강제 청산이란 바로 이 강제 종료 리스크 이벤트를 말하며, 스마트폰 버튼이 고장 난 게 아닙니다. 실제 청산가는 수수료, 유지 증거금, 마진 모드 등에 따라 달라지므로 10배 레버리지가 곧 정확한 10% 하락을 뜻하지는 않습니다."},{"t":95.25,"who":"sam","text":"나중에 다시 올랐는데, 가격이 돌아올 때까지 버틸 수는 없나요?"},{"t":99.46,"who":"nexubo","text":"청산된 포지션은 저절로 되살아나지 않습니다. '하락 후 반등'은 레버리지 포지션과 그냥 보유하고 있던 현물 간에 전혀 다른 결과를 가져옵니다."},{"t":116.25,"who":"sam","text":"전혀 보장되지 않습니다."},{"t":117.73,"who":"nexubo","text":"도착점만 중요한 게 아닙니다. 그 과정의 경로를 버텨낼 수 있느냐가 핵심입니다."},{"t":131.25,"who":"narrator","text":"가격은 거의 그대로이고 포지션을 닫지도 않았는데 잔고가 줄었습니다. 드디어 마지막 화입니다."},{"t":137.35,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]},{"ep":24,"title":"가격은 그대로인데 잔고가 줄었다? 숨은 비용까지 계산해 마지막 관문을 통과하세요","goal":"펀딩비의 방향과 산정 기준을 알고, 선물 리스크를 전면 점검하며, 거래하지 않는 결정을 내릴 수 있기.","task":"한 주기의 수수료 0.10을 계산하고 가상 선물 주문 체크리스트를 완료하세요. 실제 주문 API는 호출해선 안 됩니다.","answer":"양수 요율: 롱 포지션이 지급하고 숏 포지션이 수령. 본 예시 수수료: 0.10. 주요 위험 질문을 모두 맞히거나 명확히 거래하지 않음을 선택하면 통과.","takeaways":["펀딩비는 롱과 숏 사이에 주고받는 것이지, 거래소에 내는 고정 요금이 아닙니다.","포지션 가치를 기준으로 계산합니다. 1,000에 0.01%면 0.10입니다.","거래하지 않기로 하는 것도 합격 답안입니다."],"quiz":{"q":"펀딩비율이 양수입니다. 보통 누가 내나요?","options":["숏이 롱에게 낸다","롱이 숏에게 낸다","모두가 거래소에 낸다"],"answer":1,"why":"비율이 양수면 보통 롱이 숏에게 냅니다. 음수면 반대입니다."},"transcript":[{"t":0.25,"who":"sam","text":"가격은 거의 안 움직였고 포지션을 닫지도 않았는데, 왜 잔고가 줄었죠?"},{"t":9.25,"who":"nexubo","text":"거래 수수료 외에도 무기한 계약에는 펀딩비 메커니즘이 있습니다. 펀딩비가 양수일 때는 보통 롱이 숏에게 지불하고, 음수일 때는 반대로 바뀝니다. 모두가 거래소에 내는 고정 이자가 아닙니다."},{"t":42.25,"who":"narrator","text":"정산 시점의 포지션 가치가 1,000이고 요율이 0.01%라면, 수수료는 0.10입니다. 처음에 넣은 증거금 100이 아니라 전체 포지션 가치를 기준으로 부과됩니다."},{"t":83.25,"who":"nexubo","text":"정산 주기와 요율은 페어, 거래소, 시장 상황에 따라 달라집니다. '모든 계약이 여덟 시간마다 영원히 똑같다'고 외우지 마세요. 펀딩비를 받는 것을 무위험 수익으로 여겨서도 안 됩니다."},{"t":117.25,"who":"narrator","text":"마지막 관문은 연습 전용입니다. 먼저 무엇을 어느 방향으로 거래하는지 설명하고 모드, 규모, 증거금, 자동 추가 여부, 퇴출 계획, 비용을 점검하세요. 하나라도 모르는 항목이 있다면 멈추세요. 감으로 버튼을 누르지 마세요."},{"t":144.25,"who":"sam","text":"어떻게 하는지는 알겠지만, 이 위험이 제게 맞지 않는다는 것도 알았습니다. 그래서 거래하지 않겠습니다."},{"t":149.09,"who":"nexubo","text":"그것 역시 훌륭한 합격입니다. 코스를 마쳤다고 해서 돈을 벌 수 있다는 뜻은 아닙니다. 먼저 이해하고, 그다음에 행동하세요."},{"t":161.25,"who":"nexubo","text":"어떤 거래를 하든 수수료는 계속 누적됩니다. NexuAlpha에서 거래소별 수수료를 비교하고, 반드시 공식 사이트만을 이용하세요."},{"t":172.75,"who":"narrator","text":"두 시즌을 모두 마쳤습니다. 가장 어렵게 느껴졌던 회차를 골라 거래하기 전에 다시 한 번 복습하세요."},{"t":178.65,"who":"narrator","text":"먼저 이해하고, 그다음에 행동하세요."}]}]});
